export type Phase = 'playing' | 'paused' | 'won' | 'lost';

export interface Platform { x: number; y: number; w: number; h: number; oneWay: boolean; }

export interface Bullet { x: number; y: number; vx: number; vy: number; life: number; friendly: boolean; }
export interface Particle { x: number; y: number; vx: number; vy: number; life: number; max: number; color: string; size: number; }

export type EnemyKind = 'patrol' | 'jumper' | 'turret' | 'boss';

export interface Enemy {
  kind: EnemyKind;
  x: number; y: number; w: number; h: number;
  vx: number; vy: number;
  hp: number; maxHp: number;
  facing: number;
  cooldown: number;
  baseX: number; baseY: number;
  phase: number;
  alive: boolean;
  flash: number;
  active: boolean;
}

export interface InputState {
  left: boolean; right: boolean; up: boolean; down: boolean;
  shoot: boolean; jump: boolean; jumpHeld: boolean;
}

export interface Player {
  x: number; y: number; w: number; h: number;
  vx: number; vy: number;
  facing: number;
  onGround: boolean;
  crouching: boolean;
  invuln: number;
  blink: number;
  shootCooldown: number;
  jumpPressed: boolean;
  aimX: number;
  aimY: number;
  muzzle: number;
}

export interface Crate { x: number; y: number; w: number; h: number; hp: number; }

export interface LevelDef {
  width: number;
  groundY: number;
  platforms: Platform[];
  enemies: Enemy[];
  crates: Crate[];
}

export interface GameState {
  phase: Phase;
  player: Player;
  enemies: Enemy[];
  bullets: Bullet[];
  particles: Particle[];
  platforms: Platform[];
  crates: Crate[];
  camX: number;
  levelWidth: number;
  groundY: number;
  lives: number;
  score: number;
  checkpointX: number;
  time: number;
  shake: number;
  bossActive: boolean;
  bossDefeated: boolean;
  progress: number;
  hint: string;
  hintTimer: number;
  isTouch: boolean;
  shots: number;
  kills: number;
  lastEvent: string;
  eventSeq: number;
  started: boolean;
  moveCount: number;
  actionLog: string[];
  flashTimer: number;
}

export const VIEW_W = 960;
export const VIEW_H = 540;
export const GRAVITY = 1900;
export const PLAYER_SPEED = 250;
export const JUMP_VEL = -640;
export const PLAYER_SHOT_CD = 0.13;

export function createLevel(): LevelDef {
  const groundY = 440;
  const platforms: Platform[] = [
    { x: -80, y: groundY, w: 760, h: 200, oneWay: false },
    { x: 700, y: groundY, w: 520, h: 200, oneWay: false },
    { x: 1240, y: groundY, w: 380, h: 200, oneWay: false },
    { x: 1630, y: groundY, w: 620, h: 200, oneWay: false },
    { x: 2280, y: groundY, w: 420, h: 200, oneWay: false },
    { x: 2720, y: groundY, w: 640, h: 200, oneWay: false },
    { x: 3380, y: groundY, w: 900, h: 200, oneWay: false },
    { x: 520, y: 330, w: 140, h: 16, oneWay: true },
    { x: 820, y: 310, w: 150, h: 16, oneWay: true },
    { x: 1080, y: 360, w: 130, h: 16, oneWay: true },
    { x: 1320, y: 290, w: 160, h: 16, oneWay: true },
    { x: 1580, y: 350, w: 140, h: 16, oneWay: true },
    { x: 1820, y: 280, w: 160, h: 16, oneWay: true },
    { x: 2080, y: 340, w: 150, h: 16, oneWay: true },
    { x: 2400, y: 290, w: 160, h: 16, oneWay: true },
    { x: 2680, y: 340, w: 180, h: 16, oneWay: true },
    { x: 3000, y: 270, w: 200, h: 16, oneWay: true },
    { x: 3350, y: 350, w: 160, h: 16, oneWay: true },
  ];
  const mk = (kind: EnemyKind, x: number, y: number, w: number, h: number, hp: number): Enemy => ({
    kind, x, y, w, h, vx: 0, vy: 0, hp, maxHp: hp, facing: -1,
    cooldown: 0.6 + Math.random() * 0.6, baseX: x, baseY: y, phase: Math.random() * 6.28,
    alive: true, flash: 0, active: false,
  });
  const enemies: Enemy[] = [];
  enemies.push(mk('patrol', 480, groundY - 44, 36, 44, 2));
  enemies.push(mk('patrol', 620, groundY - 44, 36, 44, 2));
  enemies.push(mk('turret', 900, 330 - 40, 46, 40, 4));
  enemies.push(mk('patrol', 1000, groundY - 44, 36, 44, 2));
  enemies.push(mk('jumper', 1200, groundY - 44, 38, 44, 3));
  enemies.push(mk('turret', 1380, 290 - 40, 46, 40, 4));
  enemies.push(mk('patrol', 1500, groundY - 44, 36, 44, 2));
  enemies.push(mk('jumper', 1780, groundY - 44, 38, 44, 3));
  enemies.push(mk('turret', 1900, 280 - 40, 46, 40, 4));
  enemies.push(mk('patrol', 2000, groundY - 44, 36, 44, 2));
  enemies.push(mk('patrol', 2200, groundY - 44, 36, 44, 2));
  enemies.push(mk('turret', 2450, 290 - 40, 46, 40, 4));
  enemies.push(mk('jumper', 2600, groundY - 44, 38, 44, 3));
  enemies.push(mk('patrol', 2900, groundY - 44, 36, 44, 2));
  enemies.push(mk('turret', 3050, 270 - 40, 46, 40, 5));
  enemies.push(mk('patrol', 3320, groundY - 44, 36, 44, 2));
  enemies.push(mk('boss', 3860, groundY - 150, 110, 150, 60));
  const crates: Crate[] = [
    { x: 380, y: groundY - 40, w: 40, h: 40, hp: 2 },
    { x: 1680, y: groundY - 40, w: 40, h: 40, hp: 2 },
    { x: 2140, y: groundY - 40, w: 40, h: 40, hp: 2 },
    { x: 3480, y: groundY - 40, w: 40, h: 40, hp: 2 },
  ];
  return { width: 4100, groundY, platforms, enemies, crates };
}

function overlap(a: {x:number;y:number;w:number;h:number}, b: {x:number;y:number;w:number;h:number}): boolean {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

export function createState(isTouch = false): GameState {
  const level = createLevel();
  return {
    phase: 'playing',
    player: {
      x: 80, y: level.groundY - 56, w: 32, h: 56,
      vx: 0, vy: 0, facing: 1, onGround: true, crouching: false,
      invuln: 1.2, blink: 1.2, shootCooldown: 0, jumpPressed: false,
      aimX: 1, aimY: 0, muzzle: 0,
    },
    enemies: level.enemies.map(e => ({ ...e })),
    bullets: [],
    particles: [],
    platforms: level.platforms.map(p => ({ ...p })),
    crates: level.crates.map(c => ({ ...c })),
    camX: 0,
    levelWidth: level.width,
    groundY: level.groundY,
    lives: 3,
    score: 0,
    checkpointX: 80,
    time: 0,
    shake: 0,
    bossActive: false,
    bossDefeated: false,
    progress: 0,
    hint: '向右推进！',
    hintTimer: 2.5,
    isTouch,
    shots: 0,
    kills: 0,
    lastEvent: '',
    eventSeq: 0,
    started: false,
    moveCount: 0,
    actionLog: [],
    flashTimer: 0,
  };
}

function spawnParticles(s: GameState, x: number, y: number, count: number, color: string, power = 220) {
  for (let i = 0; i < count; i++) {
    const a = Math.random() * Math.PI * 2;
    const sp = Math.random() * power + 60;
    s.particles.push({
      x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 40,
      life: 0.5 + Math.random() * 0.35, max: 0.85, color, size: 2 + Math.random() * 3,
    });
  }
}

function pushEvent(s: GameState, name: string) {
  s.lastEvent = name;
  s.eventSeq += 1;
  s.actionLog.push(name);
  if (s.actionLog.length > 40) s.actionLog.shift();
}

export function respawnPlayer(s: GameState) {
  s.player.x = s.checkpointX;
  s.player.y = s.groundY - 56;
  s.player.h = 56;
  s.player.crouching = false;
  s.player.vx = 0;
  s.player.vy = 0;
  s.player.invuln = 2.2;
  s.player.blink = 2.2;
  s.player.shootCooldown = 0;
  s.camX = Math.max(0, Math.min(s.checkpointX - VIEW_W * 0.35, s.levelWidth - VIEW_W));
  s.bullets = s.bullets.filter(b => b.friendly);
}

export function playerHit(s: GameState) {
  if (s.player.invuln > 0 || s.phase !== 'playing') return;
  s.lives -= 1;
  s.shake = 14;
  s.flashTimer = 0.18;
  spawnParticles(s, s.player.x + 16, s.player.y + 28, 26, '#ff6a3d', 300);
  spawnParticles(s, s.player.x + 16, s.player.y + 28, 10, '#ffe066', 220);
  pushEvent(s, 'player-hit');
  if (s.lives <= 0) {
    s.phase = 'lost';
    s.hint = '任务失败';
    return;
  }
  respawnPlayer(s);
  s.hint = `生命 -1  剩余 ${s.lives}`;
  s.hintTimer = 1.8;
}

function firePlayerBullet(s: GameState, inx: InputState) {
  const p = s.player;
  const speed = 760;
  const facing = p.facing;
  let ax = facing, ay = 0;
  const horizontal = inx.left || inx.right;
  if (inx.up && !inx.down) {
    if (horizontal) { ax = facing * 0.7071; ay = -0.7071; }
    else { ax = 0; ay = -1; }
  } else if (inx.down) {
    if (!p.onGround) {
      if (horizontal) { ax = facing * 0.7071; ay = 0.7071; }
      else { ax = 0; ay = 1; }
    } else if (p.crouching) {
      if (horizontal) { ax = facing * 0.7071; ay = 0.7071; }
      else { ax = facing; ay = 0; }
    }
  }
  p.aimX = ax; p.aimY = ay; p.muzzle = 0.06;
  const gunLen = 22;
  const ox = p.x + p.w / 2 + ax * gunLen;
  const oy = p.y + (p.crouching ? 20 : 24) + ay * gunLen;
  s.bullets.push({ x: ox, y: oy, vx: ax * speed, vy: ay * speed, life: 1.6, friendly: true });
  s.player.shootCooldown = PLAYER_SHOT_CD;
  s.shake = Math.max(s.shake, 1.2);
  s.shots += 1;
  pushEvent(s, 'shoot');
}

function enemyFire(s: GameState, e: Enemy, tx: number, ty: number, speed: number) {
  const sx = e.x + e.w / 2;
  const sy = e.y + e.h / 2;
  const dx = tx - sx;
  const dy = ty - sy;
  const d = Math.hypot(dx, dy) || 1;
  s.bullets.push({ x: sx, y: sy, vx: (dx / d) * speed, vy: (dy / d) * speed, life: 3, friendly: false });
}

export function update(s: GameState, inx: InputState, dt: number) {
  if (s.phase !== 'playing') return;
  s.time += dt;
  s.shake = Math.max(0, s.shake - dt * 30);
  s.hintTimer = Math.max(0, s.hintTimer - dt);
  if (s.flashTimer > 0) s.flashTimer -= dt;
  const p = s.player;
  if (p.invuln > 0) p.invuln -= dt;
  if (p.blink > 0) p.blink -= dt;
  if (p.shootCooldown > 0) p.shootCooldown -= dt;
  if (p.muzzle > 0) p.muzzle -= dt;

  if (inx.left && !inx.right) p.facing = -1;
  else if (inx.right && !inx.left) p.facing = 1;

  const wantCrouch = inx.down && p.onGround && !inx.up;
  if (wantCrouch && !p.crouching) {
    p.crouching = true;
    p.y += 22;
    p.h = 34;
  } else if (!wantCrouch && p.crouching) {
    p.crouching = false;
    p.y -= 22;
    p.h = 56;
  }

  let move = 0;
  if (inx.left) move -= 1;
  if (inx.right) move += 1;
  if (p.crouching) move = 0;
  p.vx = move * PLAYER_SPEED;
  if (move !== 0) s.moveCount += 1;

  if (inx.jump && !p.jumpPressed && p.onGround && !p.crouching) {
    p.vy = JUMP_VEL;
    p.onGround = false;
    pushEvent(s, 'jump');
  }
  p.jumpPressed = inx.jump;
  if (!inx.jumpHeld && p.vy < -180) p.vy = -180;

  p.vy += GRAVITY * dt;
  if (p.vy > 1400) p.vy = 1400;

  p.x += p.vx * dt;
  resolveWorldX(s, p);
  const prevBottom = p.y + p.h;
  p.y += p.vy * dt;
  p.onGround = false;
  resolveWorldY(s, p, prevBottom);

  if (p.y > 620) { playerHit(s); return; }
  if (p.x < 0) p.x = 0;
  if (p.x > s.levelWidth - p.w) p.x = s.levelWidth - p.w;

  if (p.x > 1500 && s.checkpointX < 1500) s.checkpointX = 1500;
  if (p.x > 2600 && s.checkpointX < 2600) s.checkpointX = 2600;

  if (inx.shoot && p.shootCooldown <= 0) firePlayerBullet(s, inx);

  if (!s.bossActive && p.x > 3520) {
    s.bossActive = true;
    s.hint = '重装炮台出现！';
    s.hintTimer = 2.2;
    s.shake = 8;
  }

  for (const e of s.enemies) {
    if (!e.alive) continue;
    if (e.flash > 0) e.flash -= dt;
    if (!e.active && e.kind !== 'boss') {
      if (Math.abs((e.x + e.w / 2) - (s.camX + VIEW_W / 2)) < VIEW_W * 0.9) e.active = true;
    }
    if (e.kind === 'boss') {
      if (!s.bossActive) continue;
      e.active = true;
    }
    if (!e.active) continue;
    updateEnemy(s, e, dt);
  }

  for (const b of s.bullets) {
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.life -= dt;
  }

  for (const b of s.bullets) {
    if (b.life <= 0 || !b.friendly) continue;
    for (const e of s.enemies) {
      if (!e.alive || !e.active) continue;
      if (b.x > e.x && b.x < e.x + e.w && b.y > e.y && b.y < e.y + e.h) {
        e.hp -= 1;
        e.flash = 0.12;
        b.life = 0;
        spawnParticles(s, b.x, b.y, 5, '#ffd24a', 160);
        if (e.hp <= 0) {
          e.alive = false;
          const pts = e.kind === 'boss' ? 2000 : e.kind === 'turret' ? 250 : e.kind === 'jumper' ? 150 : 100;
          s.score += pts;
          s.kills += 1;
          s.shake = Math.max(s.shake, e.kind === 'boss' ? 20 : 8);
          spawnParticles(s, e.x + e.w/2, e.y + e.h/2, e.kind === 'boss' ? 46 : 16, '#ff8a3d', e.kind === 'boss' ? 420 : 240);
          spawnParticles(s, e.x + e.w/2, e.y + e.h/2, e.kind === 'boss' ? 24 : 8, '#ffe066', 200);
          pushEvent(s, 'kill');
          if (e.kind === 'boss') {
            s.bossDefeated = true;
            s.score += Math.max(0, s.lives) * 200;
            s.phase = 'won';
            s.hint = '任务完成！';
          }
        }
        break;
      }
    }
    if (b.life <= 0) continue;
    for (const c of s.crates) {
      if (c.hp <= 0) continue;
      if (b.x > c.x && b.x < c.x + c.w && b.y > c.y && b.y < c.y + c.h) {
        c.hp -= 1;
        b.life = 0;
        spawnParticles(s, b.x, b.y, 4, '#c58b3f', 140);
        break;
      }
    }
  }
  s.crates = s.crates.filter(c => c.hp > 0);

  const pBox = { x: p.x, y: p.y, w: p.w, h: p.h };
  for (const b of s.bullets) {
    if (b.life <= 0 || b.friendly) continue;
    if (b.x > pBox.x && b.x < pBox.x + pBox.w && b.y > pBox.y && b.y < pBox.y + pBox.h) {
      b.life = 0;
      playerHit(s);
    }
  }
  if (s.phase === 'playing') {
    for (const e of s.enemies) {
      if (!e.alive || !e.active) continue;
      if (overlap(pBox, e)) playerHit(s);
    }
  }
  for (const c of s.crates) {
    if (overlap(pBox, c)) {
      if (p.vx > 0) p.x = c.x - p.w;
      else if (p.vx < 0) p.x = c.x + c.w;
    }
  }

  s.bullets = s.bullets.filter(b => b.life > 0 && b.x > s.camX - 200 && b.x < s.camX + VIEW_W + 200 && b.y > -100 && b.y < VIEW_H + 120);
  for (const pt of s.particles) {
    pt.vy += 900 * dt;
    pt.x += pt.vx * dt;
    pt.y += pt.vy * dt;
    pt.life -= dt;
  }
  s.particles = s.particles.filter(pt => pt.life > 0);

  const targetCam = Math.max(0, Math.min(p.x - VIEW_W * 0.35, s.levelWidth - VIEW_W));
  s.camX += (targetCam - s.camX) * Math.min(1, dt * 8);
  s.progress = Math.min(1, Math.max(0, p.x / (s.levelWidth - 220)));
}

function resolveWorldX(s: GameState, p: Player) {
  for (const pl of s.platforms) {
    if (pl.oneWay) continue;
    if (overlap(p, pl)) {
      if (p.vx > 0) p.x = pl.x - p.w;
      else if (p.vx < 0) p.x = pl.x + pl.w;
    }
  }
}

function resolveWorldY(s: GameState, p: Player, prevBottom: number) {
  for (const pl of s.platforms) {
    if (!overlap(p, pl)) continue;
    if (p.vy >= 0) {
      if (pl.oneWay) {
        if (prevBottom > pl.y + 6) continue;
      }
      p.y = pl.y - p.h;
      if (p.vy > 400) spawnParticles(s, p.x + p.w/2, p.y + p.h, 5, '#8fbf6a', 100);
      p.vy = 0;
      p.onGround = true;
    } else if (p.vy < 0) {
      if (pl.oneWay) continue;
      p.y = pl.y + pl.h;
      p.vy = 0;
    }
  }
}

function updateEnemy(s: GameState, e: Enemy, dt: number) {
  const p = s.player;
  const px = p.x + p.w / 2;
  const py = p.y + p.h / 2;
  const ex = e.x + e.w / 2;
  const ey = e.y + e.h / 2;
  const dx = px - ex;
  const dy = py - ey;
  const dist = Math.hypot(dx, dy);
  e.cooldown -= dt;
  if (e.kind === 'patrol') {
    e.vx = e.facing * 55;
    e.x += e.vx * dt;
    if (Math.abs(e.x - e.baseX) > 110) e.facing *= -1;
    e.y += 300 * dt;
    for (const pl of s.platforms) {
      if (overlap(e, pl) && e.y + e.h - 6 < pl.y + 12) e.y = pl.y - e.h;
    }
    if (dist < 380 && Math.abs(dy) < 180 && e.cooldown <= 0 && px > e.x - 20) {
      e.facing = dx < 0 ? -1 : 1;
      enemyFire(s, e, px, py, 320);
      e.cooldown = 1.4 + Math.random() * 0.6;
    }
  } else if (e.kind === 'jumper') {
    e.vy += GRAVITY * dt;
    e.x += e.vx * dt;
    e.y += e.vy * dt;
    for (const pl of s.platforms) {
      if (!pl.oneWay && overlap(e, pl)) {
        if (e.vy > 0) { e.y = pl.y - e.h; e.vy = 0; } else { e.y = pl.y + pl.h; e.vy = 0; }
      }
    }
    const onGround = Math.abs((e.y + e.h) - s.groundY) < 4;
    if (onGround) {
      e.vx = 0;
      if (e.cooldown <= 0 && dist < 440) {
        e.vy = -520;
        e.vx = dx < 0 ? -180 : 180;
        e.cooldown = 1.6;
      }
    }
    if (dist < 400 && Math.abs(dy) < 220 && e.cooldown <= 0 && Math.random() < 0.03) {
      enemyFire(s, e, px, py, 340);
      e.cooldown = 1.2;
    }
    if (e.y > 720) { e.y = s.groundY - e.h; e.vy = 0; e.vx = 0; }
  } else if (e.kind === 'turret') {
    if (dist < 520 && e.cooldown <= 0) {
      enemyFire(s, e, px, py, 300);
      e.cooldown = 1.4;
    }
  } else if (e.kind === 'boss') {
    e.phase += dt;
    const hpRatio = e.hp / e.maxHp;
    e.y = e.baseY + Math.sin(e.phase * 1.3) * 6;
    if (e.cooldown <= 0) {
      if (hpRatio > 0.65) {
        enemyFire(s, e, px, py, 300);
        e.cooldown = 1.1;
      } else if (hpRatio > 0.33) {
        for (let i = -2; i <= 2; i++) {
          const ang = Math.atan2(py - (e.y + 60), px - (e.x + e.w / 2)) + i * 0.18;
          s.bullets.push({ x: e.x + e.w / 2 - 12, y: e.y + 70, vx: Math.cos(ang) * 300, vy: Math.sin(ang) * 300, life: 3, friendly: false });
        }
        e.cooldown = 1.35;
      } else {
        for (let i = 0; i < 8; i++) {
          const ang = (i / 8) * Math.PI * 2;
          s.bullets.push({ x: e.x + e.w / 2 - 12, y: e.y + 70, vx: Math.cos(ang) * 260, vy: Math.sin(ang) * 260, life: 3.2, friendly: false });
        }
        e.cooldown = 1.0;
      }
    }
  }
}

export function tick(s: GameState, inx: InputState, rawDt: number) {
  let dt = rawDt;
  if (dt > 0.05) dt = 0.05;
  update(s, inx, dt);
}

export function getBoss(s: GameState): Enemy | undefined {
  return s.enemies.find(e => e.kind === 'boss');
}

