import type { GameState, Phase } from '../game/engine';

interface Props {
  state: GameState;
  onRestart: () => void;
  onPauseToggle: () => void;
  muted: boolean;
  onMuteToggle: () => void;
  best: number;
}

export default function GameHud({ state, onRestart, onPauseToggle, muted, onMuteToggle, best }: Props) {
  const boss = state.enemies.find(e => e.kind === 'boss');
  const bossShown = state.bossActive && boss && boss.alive;
  const pct = Math.round(state.progress * 100);
  const phase: Phase = state.phase;

  return (
    <div className="hud" data-hud-phase={phase} data-game-phase={phase} style={{ pointerEvents: 'none' }}>
      <div className="hud-top">
        <div className="hud-block">
          <div className="hud-label">生命</div>
          <div className="hud-lives" data-hud="lives" data-live="lives" aria-label={`生命 ${Math.max(0, state.lives)}`}>
            {Array.from({ length: Math.max(0, state.lives) }).map((_, i) => (
              <span key={i} className="life-dot" />
            ))}
            {state.lives <= 0 && <span className="life-dot dead" />}
          </div>
        </div>
        <div className="hud-block center">
          <div className="hud-label">丛林基地 · 进度 {pct}%</div>
          <div className="progress">
            <div className="progress-fill" style={{ width: `${pct}%` }} data-live="progress" />
            <div className="progress-ticks">
              <span style={{ left: '0%' }} />
              <span style={{ left: '37%' }} />
              <span style={{ left: '63%' }} />
              <span style={{ left: '100%' }} />
            </div>
          </div>
        </div>
        <div className="hud-block right">
          <div className="hud-right-text">
            <div className="hud-label">得分</div>
            <div className="hud-score" data-hud="score" data-live="score">{String(state.score).padStart(6, '0')}</div>
          </div>
          <div className="hud-buttons">
            <button type="button" className="hud-btn" onClick={onMuteToggle} aria-label="静音" title="静音">{muted ? '🔇' : '🔊'}</button>
            <button type="button" className="hud-btn" onClick={onPauseToggle} aria-label="暂停" title="暂停">{state.phase === 'paused' ? '▶' : '❚❚'}</button>
          </div>
        </div>
      </div>

      {bossShown && (
        <div className="boss-bar-wrap">
          <div className="boss-label">重装炮台</div>
          <div className="boss-bar">
            <div className="boss-fill" style={{ width: `${Math.max(0, (boss!.hp / boss!.maxHp) * 100)}%` }} />
          </div>
        </div>
      )}

      {state.hintTimer > 0 && state.phase === 'playing' && (
        <div className="hint-bar">{state.hint}</div>
      )}

      {state.phase === 'paused' && (
        <div className="overlay" data-game-phase="paused">
          <div className="panel">
            <h2>任务暂停</h2>
            <p className="muted">A/D 或 ←/→ 移动 · W 上瞄准 · S 蹲伏/下瞄准</p>
            <p className="muted">J 或 Z 射击 · K 或 X 跳跃 · Esc 继续 · R 重开</p>
            <div className="panel-row">
              <button type="button" className="btn primary" onClick={onPauseToggle} data-action="resume">继续</button>
              <button type="button" className="btn" onClick={onRestart} data-action="restart">重开</button>
            </div>
          </div>
        </div>
      )}

      {state.phase === 'won' && (
        <div className="overlay" data-game-phase="won">
          <div className="panel">
            <h2 className="success">任务完成</h2>
            <p>重装炮台已被摧毁，丛林基地安全。</p>
            <p className="big-score">{String(state.score).padStart(6, '0')}</p>
            <p className="muted">击毁 {state.kills} 个目标 · 射击 {state.shots} 发 · 剩余生命 {Math.max(0, state.lives)}</p>
            {best > 0 && <p className="muted">最佳纪录 {String(best).padStart(6, '0')}</p>}
            <button type="button" className="btn primary" onClick={onRestart} data-game-start data-action="restart">再战一局</button>
          </div>
        </div>
      )}

      {state.phase === 'lost' && (
        <div className="overlay" data-game-phase="lost">
          <div className="panel">
            <h2 className="fail">任务失败</h2>
            <p>你的生命已经耗尽。</p>
            <p className="big-score">{String(state.score).padStart(6, '0')}</p>
            <p className="muted">进度 {pct}% · 最佳 {String(best).padStart(6, '0')}</p>
            <button type="button" className="btn primary" onClick={onRestart} data-game-start data-action="restart">重新部署</button>
          </div>
        </div>
      )}
    </div>
  );
}

