import { useCallback, useEffect, useRef, useState } from 'react';
import {
  createState, tick, type GameState, type InputState,
  VIEW_W, VIEW_H,
} from './game/engine';
import GameHud from './components/GameHud';
import { renderGame } from './game/renderer';
import { audio } from './game/audio';

const emptyInput: InputState = {
  left: false, right: false, up: false, down: false,
  shoot: false, jump: false, jumpHeld: false,
};

interface StorageLike {
  get: (k: string) => string | null;
  set: (k: string, v: string) => void;
  flush?: () => void;
}

function getStorage(): StorageLike | null {
  if (typeof window === 'undefined') return null;
  const w = window as unknown as { atoms?: { storage?: StorageLike } };
  return w.atoms?.storage ?? null;
}

function detectTouch(): boolean {
  if (typeof window === 'undefined') return false;
  try {
    return !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
  } catch {
    return false;
  }
}

const STORE_KEY = 'contra_jungle_highscore';
type PadName = 'left'|'right'|'up'|'down'|'shoot'|'jump';

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const stateRef = useRef<GameState>(createState(detectTouch()));
  const inputRef = useRef<InputState>({ ...emptyInput });
  const mutedRef = useRef(false);
  const highScoreRef = useRef(0);
  const lastSeqRef = useRef<number>(0);
  const lastShootSoundRef = useRef(0);
  const savedRef = useRef(false);
  const [muted, setMuted] = useState(false);
  const [isTouch] = useState<boolean>(() => detectTouch());
  const [best, setBest] = useState(0);
  const [snap, setSnap] = useState<GameState>(() => ({ ...stateRef.current }));

  useEffect(() => {
    const st = getStorage();
    if (!st) return;
    try {
      const v = st.get(STORE_KEY);
      if (v) {
        const n = Math.max(0, parseInt(v, 10) || 0);
        highScoreRef.current = n;
        setBest(n);
      }
    } catch { /* ignore */ }
  }, []);

  const saveHighScore = useCallback((score: number) => {
    if (score <= highScoreRef.current) return;
    highScoreRef.current = score;
    setBest(score);
    const st = getStorage();
    if (!st) return;
    try {
      st.set(STORE_KEY, String(score));
      st.flush && st.flush();
    } catch { /* ignore */ }
  }, []);

  const triggerRender = useCallback(() => {
    const c = canvasRef.current;
    if (!c) return;
    const ctx = c.getContext('2d');
    if (!ctx) return;
    renderGame(ctx, stateRef.current, highScoreRef.current);
  }, []);

  useEffect(() => {
    let raf = 0;
    let last = performance.now();
    let acc = 0;
    let lastSnapAt = 0;
    const step = 1 / 60;
    const loop = (t: number) => {
      raf = requestAnimationFrame(loop);
      const s = stateRef.current;
      let dt = (t - last) / 1000;
      last = t;
      if (dt > 0.1) dt = 0.1;
      if (dt < 0) dt = 0;
      if (s.phase === 'playing') {
        acc += dt;
        let guard = 0;
        while (acc >= step && guard < 6) {
          tick(s, inputRef.current, step);
          acc -= step;
          guard++;
          if (s.phase !== 'playing') break;
        }
        if (guard >= 6) acc = 0;
        if (!s.started) s.started = true;
      } else {
        acc = 0;
      }

      if (s.eventSeq !== lastSeqRef.current) {
        lastSeqRef.current = s.eventSeq;
        if (s.lastEvent === 'shoot') {
          const now = performance.now();
          if (now - lastShootSoundRef.current > 55) { audio.shoot(); lastShootSoundRef.current = now; }
        } else if (s.lastEvent === 'kill') {
          audio.hit();
        } else if (s.lastEvent === 'player-hit') {
          audio.hit();
        }
      }

      if (s.phase === 'won' || s.phase === 'lost') {
        if (!savedRef.current) {
          savedRef.current = true;
          saveHighScore(s.score);
        }
      } else {
        savedRef.current = false;
      }

      triggerRender();

      if (t - lastSnapAt > 90) {
        lastSnapAt = t;
        setSnap({ ...s, player: { ...s.player }, enemies: s.enemies.map(e => ({ ...e })) });
      }
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [triggerRender, saveHighScore]);

  useEffect(() => {
    const resize = () => {
      const wrap = wrapRef.current;
      const c = canvasRef.current;
      if (!wrap || !c) return;
      const rect = wrap.getBoundingClientRect();
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const aspect = VIEW_W / VIEW_H;
      let cssW = rect.width;
      let cssH = rect.height;
      if (!cssW || !cssH) return;
      if (cssW / cssH > aspect) cssW = cssH * aspect;
      else cssH = cssW / aspect;
      c.style.width = `${cssW}px`;
      c.style.height = `${cssH}px`;
      c.width = Math.round(VIEW_W * dpr);
      c.height = Math.round(VIEW_H * dpr);
      const ctx = c.getContext('2d');
      if (ctx) ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      triggerRender();
    };
    resize();
    window.addEventListener('resize', resize);
    const id = window.setTimeout(resize, 60);
    return () => {
      window.removeEventListener('resize', resize);
      window.clearTimeout(id);
    };
  }, [triggerRender]);

  const pause = useCallback(() => {
    if (stateRef.current.phase !== 'playing') return;
    stateRef.current.phase = 'paused';
    audio.stopAll();
    inputRef.current = { ...emptyInput };
    setSnap({ ...stateRef.current, player: { ...stateRef.current.player } });
  }, []);

  const resume = useCallback(() => {
    if (stateRef.current.phase === 'paused') {
      stateRef.current.phase = 'playing';
      setSnap({ ...stateRef.current, player: { ...stateRef.current.player } });
    }
  }, []);

  const togglePause = useCallback(() => {
    if (stateRef.current.phase === 'paused') resume();
    else if (stateRef.current.phase === 'playing') pause();
  }, [pause, resume]);

  const restart = useCallback(() => {
    saveHighScore(stateRef.current.score);
    stateRef.current = createState(isTouch);
    inputRef.current = { ...emptyInput };
    savedRef.current = false;
    lastSeqRef.current = 0;
    setSnap({ ...stateRef.current, player: { ...stateRef.current.player } });
    wrapRef.current?.focus?.({ preventScroll: true });
    requestAnimationFrame(() => triggerRender());
  }, [isTouch, saveHighScore, triggerRender]);

  const toggleMute = useCallback(() => {
    mutedRef.current = !mutedRef.current;
    setMuted(mutedRef.current);
    audio.setMuted(mutedRef.current);
  }, []);

  useEffect(() => {
    const onDown = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement | null)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') return;
      const inp = inputRef.current;
      switch (e.code) {
        case 'KeyA': case 'ArrowLeft': inp.left = true; e.preventDefault(); break;
        case 'KeyD': case 'ArrowRight': inp.right = true; e.preventDefault(); break;
        case 'KeyW': case 'ArrowUp': inp.up = true; e.preventDefault(); break;
        case 'KeyS': case 'ArrowDown': inp.down = true; e.preventDefault(); break;
        case 'KeyJ': case 'KeyZ': inp.shoot = true; e.preventDefault(); break;
        case 'KeyK': case 'KeyX': case 'Space':
          inp.jump = true; inp.jumpHeld = true; e.preventDefault(); break;
        case 'Escape': togglePause(); break;
        case 'KeyR': restart(); break;
      }
    };
    const onUp = (e: KeyboardEvent) => {
      const inp = inputRef.current;
      switch (e.code) {
        case 'KeyA': case 'ArrowLeft': inp.left = false; break;
        case 'KeyD': case 'ArrowRight': inp.right = false; break;
        case 'KeyW': case 'ArrowUp': inp.up = false; break;
        case 'KeyS': case 'ArrowDown': inp.down = false; break;
        case 'KeyJ': case 'KeyZ': inp.shoot = false; break;
        case 'KeyK': case 'KeyX': case 'Space':
          inp.jump = false; inp.jumpHeld = false; break;
      }
    };
    const onBlur = () => {
      inputRef.current = { ...emptyInput };
    };
    window.addEventListener('keydown', onDown);
    window.addEventListener('keyup', onUp);
    window.addEventListener('blur', onBlur);
    return () => {
      window.removeEventListener('keydown', onDown);
      window.removeEventListener('keyup', onUp);
      window.removeEventListener('blur', onBlur);
    };
  }, [restart, togglePause]);

  const pointerMap = useRef<Map<number, PadName>>(new Map());

  const applyName = useCallback((name: PadName, on: boolean) => {
    const inp = inputRef.current;
    switch (name) {
      case 'left': inp.left = on; break;
      case 'right': inp.right = on; break;
      case 'up': inp.up = on; break;
      case 'down': inp.down = on; break;
      case 'shoot': inp.shoot = on; break;
      case 'jump': inp.jump = on; inp.jumpHeld = on; break;
    }
  }, []);

  const pulseName = useCallback((name: PadName, dur: number) => {
    applyName(name, true);
    window.setTimeout(() => {
      let held = false;
      pointerMap.current.forEach(v => { if (v === name) held = true; });
      if (!held) applyName(name, false);
    }, dur);
  }, [applyName]);

  const onBtnDown = (name: PadName) => (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const s = stateRef.current;
    if (s.phase === 'paused') resume();
    if (s.phase !== 'playing') return;
    pointerMap.current.set(e.pointerId, name);
    applyName(name, true);
    try { (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); } catch { /* ignore */ }
  };

  const releasePointer = useCallback((pointerId: number) => {
    const name = pointerMap.current.get(pointerId);
    if (!name) return;
    pointerMap.current.delete(pointerId);
    let stillDown = false;
    pointerMap.current.forEach(v => { if (v === name) stillDown = true; });
    if (!stillDown) applyName(name, false);
  }, [applyName]);

  const onBtnUp = (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    releasePointer(e.pointerId);
  };

  const onPadClick = (name: PadName) => (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const s = stateRef.current;
    if (s.phase === 'paused') resume();
    if (s.phase !== 'playing') return;
    pulseName(name, name === 'jump' ? 200 : 150);
  };

  const btnProps = (name: PadName) => ({
    onPointerDown: onBtnDown(name),
    onPointerUp: onBtnUp,
    onPointerCancel: onBtnUp,
    onPointerLeave: onBtnUp,
    onClick: onPadClick(name),
    onContextMenu: (e: React.MouseEvent) => e.preventDefault(),
    'data-pad': name,
  } as const);

  const onCanvasClick = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    const s = stateRef.current;
    if (s.phase === 'paused') resume();
    if (s.phase !== 'playing') return;
    pulseName('shoot', 200);
  }, [pulseName, resume]);

  const onKeyButton = (key: PadName) => (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    onPadClick(key)(e);
  };

  const s = snap;

  return (
    <div className="game-root">
      <header className="top-title">
        <div className="game-title">丛林突击 · JUNGLE STRIKE</div>
        <div className="title-sub">魂斗罗风格横版射击</div>
        <div className="live-status">
          得分 <b data-live="score">{String(s.score).padStart(6, '0')}</b> · 生命 <b data-live="lives">{Math.max(0, s.lives)}</b> · 进度 <b data-live="progress">{Math.round(s.progress * 100)}%</b>
        </div>
      </header>
      <div
        className="stage"
        ref={wrapRef}
        tabIndex={0}
        data-game-root
        data-game-phase={s.phase}
        data-game-progress={Math.round(s.progress * 100)}
        data-game-score={s.score}
        data-game-lives={s.lives}
        data-game-shots={s.shots}
        data-game-moves={s.moveCount}
        data-game-events={s.eventSeq}
        onPointerDown={() => { wrapRef.current?.focus?.({ preventScroll: true }); }}
      >
        <canvas
          ref={canvasRef}
          className="game-canvas"
          data-game-actions="移动 瞄准 射击 跳跃"
          onClick={onCanvasClick}
        />
        <GameHud
          state={s}
          onRestart={restart}
          onPauseToggle={togglePause}
          muted={muted}
          onMuteToggle={toggleMute}
          best={best}
        />
        <div className="touch-controls" data-game-actions="左移 右移 上瞄准 下瞄准 射击 跳跃" aria-label="虚拟按键">
          <div className="tc-pad" role="group" aria-label="方向键">
            <button type="button" className="tc-btn" aria-label="左移" title="左移" data-action="left" {...btnProps('left')}>◀</button>
            <div className="tc-col">
              <button type="button" className="tc-btn small" aria-label="向上瞄准" title="向上瞄准" data-action="up" {...btnProps('up')}>▲</button>
              <button type="button" className="tc-btn small" aria-label="蹲伏或向下瞄准" title="蹲伏或向下瞄准" data-action="down" {...btnProps('down')}>▼</button>
            </div>
            <button type="button" className="tc-btn" aria-label="右移" title="右移" data-action="right" {...btnProps('right')}>▶</button>
          </div>
          <div className="tc-actions" role="group" aria-label="动作键">
            <button type="button" className="tc-btn jump" aria-label="跳跃" title="跳跃" data-action="jump" {...btnProps('jump')}>跳</button>
            <button type="button" className="tc-btn shoot" aria-label="射击" title="射击" data-action="shoot" {...btnProps('shoot')}>射</button>
          </div>
        </div>
        <div className="quick-keys" aria-label="快捷操作">
          <span className="qk-label">快捷</span>
          <button type="button" className="qk-btn" aria-label="射击" data-action="quick-shoot" onClick={onKeyButton('shoot')}>射击</button>
          <button type="button" className="qk-btn" aria-label="跳跃" data-action="quick-jump" onClick={onKeyButton('jump')}>跳跃</button>
          <button type="button" className="qk-btn" aria-label="右移" data-action="quick-right" onClick={onKeyButton('right')}>右移</button>
          <button type="button" className="qk-btn" aria-label="左移" data-action="quick-left" onClick={onKeyButton('left')}>左移</button>
        </div>
      </div>
      <footer className="tips">
        {isTouch
          ? '方向键移动与瞄准 · 射击/跳跃按钮 · 长按跳跃更高'
          : 'A/D ←/→ 移动　W ↑ 上瞄准　S ↓ 蹲伏/下瞄准　J/Z 射击　K/X 跳跃　Esc 暂停　R 重开'}
      </footer>
    </div>
  );
}

