import type { GameState, Enemy, Bullet, Particle, Player } from './engine';
import { VIEW_W, VIEW_H } from './engine';

let cloudOffset = 0;

export function renderGame(ctx: CanvasRenderingContext2D, s: GameState, highScore: number) {
  cloudOffset += 0.15;
  ctx.save();
  if (s.shake > 0.4) {
    ctx.translate((Math.random() - 0.5) * s.shake, (Math.random() - 0.5) * s.shake);
  }
  drawSky(ctx);
  drawParallax(ctx, s.camX);

  ctx.save();
  ctx.translate(-Math.round(s.camX), 0);
  drawPlatforms(ctx, s);
  drawArena(ctx, s);
  drawCrates(ctx, s);
  drawEnemies(ctx, s);
  drawPlayer(ctx, s);
  drawAimIndicator(ctx, s.player);
  drawBullets(ctx, s.bullets);
  drawParticles(ctx, s.particles);
  ctx.restore();

  if (s.flashTimer > 0) {
    ctx.fillStyle = 'rgba(255,60,40,' + Math.min(0.5, s.flashTimer * 2.5) + ')';
    ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  }

  drawVignette(ctx);
  drawMiniHighScore(ctx, highScore);
  if (s.phase === 'won' || s.phase === 'lost') {
    ctx.fillStyle = s.phase === 'won' ? 'rgba(255,200,60,0.08)' : 'rgba(160,20,20,0.18)';
    ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  }
  ctx.restore();
}

function drawSky(ctx: CanvasRenderingContext2D) {
  const g = ctx.createLinearGradient(0, 0, 0, VIEW_H);
  g.addColorStop(0, '#233b4a');
  g.addColorStop(0.45, '#4a6a5f');
  g.addColorStop(1, '#7a8a5a');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  const sun = ctx.createRadialGradient(VIEW_W * 0.7, 110, 10, VIEW_W * 0.7, 110, 220);
  sun.addColorStop(0, 'rgba(255,230,150,0.5)');
  sun.addColorStop(1, 'rgba(255,230,150,0)');
  ctx.fillStyle = sun;
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);
}

function drawParallax(ctx: CanvasRenderingContext2D, camX: number) {
  ctx.fillStyle = 'rgba(220,235,215,0.5)';
  for (let i = 0; i < 6; i++) {
    const x = ((i * 260 - camX * 0.08 + cloudOffset) % 1600 + 1600) % 1600 - 200;
    const y = 50 + (i % 3) * 32;
    puff(ctx, x, y, 46, 20);
  }
  ctx.fillStyle = '#3a5443';
  ctx.beginPath();
  ctx.moveTo(-100, 380);
  for (let i = 0; i < 12; i++) {
    const bx = i * 180 - ((camX * 0.25) % 180) - 100;
    ctx.lineTo(bx + 90, 260 + ((i * 37) % 60));
    ctx.lineTo(bx + 180, 380);
  }
  ctx.lineTo(VIEW_W + 100, 380);
  ctx.lineTo(VIEW_W + 100, VIEW_H);
  ctx.lineTo(-100, VIEW_H);
  ctx.closePath();
  ctx.fill();

  for (let i = 0; i < 14; i++) {
    const bx = i * 160 - ((camX * 0.55) % 160) - 100;
    const by = 200 + ((i * 53) % 50);
    ctx.fillStyle = '#1e3423';
    ctx.beginPath();
    ctx.arc(bx, by, 70, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#264a2e';
    ctx.beginPath();
    ctx.arc(bx - 30, by + 30, 44, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = '#3a2a1c';
  for (let i = 0; i < 8; i++) {
    const bx = i * 320 - ((camX * 0.55) % 320) - 100;
    ctx.fillRect(bx, 200, 26, 260);
  }
}

function puff(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number) {
  ctx.beginPath();
  ctx.ellipse(x, y, w, h, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(x + w * 0.7, y + 2, w * 0.7, h * 0.9, 0, 0, Math.PI * 2);
  ctx.fill();
}

function drawPlatforms(ctx: CanvasRenderingContext2D, s: GameState) {
  for (const pl of s.platforms) {
    if (pl.oneWay) {
      ctx.fillStyle = '#5b7a4a';
      ctx.fillRect(pl.x, pl.y, pl.w, pl.h);
      ctx.fillStyle = '#3d5632';
      ctx.fillRect(pl.x, pl.y + pl.h - 5, pl.w, 5);
      ctx.strokeStyle = '#8fb86a';
      ctx.lineWidth = 1;
      for (let x = pl.x + 10; x < pl.x + pl.w - 6; x += 18) {
        ctx.beginPath();
        ctx.moveTo(x, pl.y + 2);
        ctx.lineTo(x, pl.y + pl.h - 4);
        ctx.stroke();
      }
      ctx.fillStyle = '#ff5a2a';
      ctx.beginPath();
      ctx.arc(pl.x + pl.w - 8, pl.y + 4, 3, 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.fillStyle = '#33261a';
      ctx.fillRect(pl.x, pl.y, pl.w, pl.h);
      const g = ctx.createLinearGradient(0, pl.y, 0, pl.y + 30);
      g.addColorStop(0, '#5b7a45');
      g.addColorStop(1, '#3a522e');
      ctx.fillStyle = g;
      ctx.fillRect(pl.x, pl.y, pl.w, 16);
      ctx.fillStyle = '#4f6a3a';
      ctx.fillRect(pl.x, pl.y + 16, pl.w, 6);
      ctx.strokeStyle = 'rgba(20,30,16,0.7)';
      ctx.lineWidth = 2;
      for (let x = pl.x + 20; x < pl.x + pl.w; x += 44) {
        ctx.beginPath();
        ctx.moveTo(x, pl.y + 4);
        ctx.lineTo(x + 22, pl.y + 4);
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(0,0,0,0.25)';
      for (let x = pl.x + 30; x < pl.x + pl.w - 20; x += 70) {
        const yy = pl.y + 30 + ((x * 7) % 40);
        ctx.beginPath();
        ctx.ellipse(x, yy, 26, 12, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.fillRect(pl.x, pl.y, 3, pl.h);
      ctx.fillRect(pl.x + pl.w - 3, pl.y, 3, pl.h);
    }
  }
  for (let x = 200; x < s.levelWidth; x += 340) {
    ctx.fillStyle = '#2a3f2f';
    ctx.fillRect(x, s.groundY - 130, 6, 130);
    ctx.fillStyle = '#8a2f20';
    ctx.fillRect(x + 6, s.groundY - 130, 26, 18);
    ctx.fillStyle = '#ffd24a';
    ctx.fillRect(x + 34, s.groundY - 126, 3, 10);
  }
}

function drawCrates(ctx: CanvasRenderingContext2D, s: GameState) {
  for (const c of s.crates) {
    ctx.fillStyle = '#8a5a2a';
    ctx.fillRect(c.x, c.y, c.w, c.h);
    ctx.strokeStyle = '#5a3a15';
    ctx.lineWidth = 3;
    ctx.strokeRect(c.x + 2, c.y + 2, c.w - 4, c.h - 4);
    ctx.beginPath();
    ctx.moveTo(c.x + 3, c.y + 3);
    ctx.lineTo(c.x + c.w - 3, c.y + c.h - 3);
    ctx.moveTo(c.x + c.w - 3, c.y + 3);
    ctx.lineTo(c.x + 3, c.y + c.h - 3);
    ctx.stroke();
  }
}

function drawEnemies(ctx: CanvasRenderingContext2D, s: GameState) {
  for (const e of s.enemies) {
    if (!e.alive || !e.active) continue;
    drawEnemy(ctx, e);
  }
}

function drawEnemy(ctx: CanvasRenderingContext2D, e: Enemy) {
  if (e.kind === 'patrol') {
    ctx.fillStyle = e.flash > 0 ? '#ffffff' : '#a8302a';
    ctx.fillRect(e.x, e.y, e.w, e.h);
    ctx.fillStyle = '#6d1a16';
    ctx.fillRect(e.x, e.y + e.h - 12, e.w, 12);
    ctx.fillStyle = '#ffd8b0';
    ctx.fillRect(e.x + e.w - 12, e.y + 4, 8, 8);
    ctx.fillStyle = '#e9c47a';
    ctx.fillRect(e.x + (e.facing > 0 ? e.w - 2 : -8), e.y + 18, 10, 6);
    ctx.fillStyle = '#241a12';
    ctx.fillRect(e.x + 3, e.y + e.h - 8, 10, 8);
    ctx.fillRect(e.x + e.w - 13, e.y + e.h - 8, 10, 8);
  } else if (e.kind === 'jumper') {
    ctx.fillStyle = e.flash > 0 ? '#ffffff' : '#c0392b';
    ctx.fillRect(e.x, e.y, e.w, e.h);
    ctx.fillStyle = '#7a1f14';
    ctx.fillRect(e.x + 4, e.y + 10, e.w - 8, 14);
    ctx.fillStyle = '#ffd8b0';
    ctx.beginPath();
    ctx.arc(e.x + e.w / 2, e.y + 8, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#e5c04a';
    ctx.fillRect(e.x + 2, e.y + 4, e.w - 4, 5);
    ctx.fillStyle = '#2a1a10';
    ctx.fillRect(e.x + 4, e.y + e.h - 6, 10, 6);
    ctx.fillRect(e.x + e.w - 14, e.y + e.h - 6, 10, 6);
  } else if (e.kind === 'turret') {
    ctx.fillStyle = e.flash > 0 ? '#ffffff' : '#808a84';
    ctx.fillRect(e.x, e.y, e.w, e.h);
    ctx.fillStyle = '#4a5450';
    ctx.fillRect(e.x + 4, e.y + 4, e.w - 8, 10);
    ctx.fillStyle = '#2a302e';
    ctx.fillRect(e.x + e.w / 2 - 4, e.y + 12, 8, 22);
    ctx.fillStyle = '#ff5a2a';
    ctx.beginPath();
    ctx.arc(e.x + e.w / 2, e.y + 8, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#3a403e';
    ctx.lineWidth = 2;
    ctx.strokeRect(e.x + 1, e.y + 1, e.w - 2, e.h - 2);
  } else if (e.kind === 'boss') {
    ctx.fillStyle = e.flash > 0 ? '#ffffff' : '#4b5652';
    ctx.fillRect(e.x, e.y, e.w, e.h);
    ctx.fillStyle = '#2c3532';
    ctx.fillRect(e.x + 8, e.y + e.h - 30, e.w - 16, 30);
    ctx.fillStyle = '#5d6a65';
    ctx.fillRect(e.x + 10, e.y + 10, e.w - 20, 26);
    ctx.fillStyle = '#222824';
    ctx.fillRect(e.x - 26, e.y + e.h / 2 - 12, 36, 24);
    ctx.fillStyle = '#141816';
    ctx.fillRect(e.x - 34, e.y + e.h / 2 - 8, 12, 16);
    const blink = (Math.sin(performance.now() / 200) + 1) / 2;
    ctx.fillStyle = `rgba(255, 90, 40, ${0.5 + blink * 0.5})`;
    ctx.beginPath();
    ctx.arc(e.x + e.w / 2, e.y + 30, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#1c221f';
    ctx.lineWidth = 2;
    for (let y = e.y + 50; y < e.y + e.h - 20; y += 18) {
      ctx.beginPath();
      ctx.moveTo(e.x + 6, y);
      ctx.lineTo(e.x + e.w - 6, y);
      ctx.stroke();
    }
    ctx.fillStyle = '#1a1e1b';
    ctx.fillRect(e.x - 8, e.y + e.h - 14, e.w + 16, 14);
  }
}

function drawPlayer(ctx: CanvasRenderingContext2D, s: GameState) {
  const p = s.player;
  if (p.invuln > 0 && Math.floor(p.blink * 14) % 2 === 0) return;
  const cx = p.x + p.w / 2;
  ctx.fillStyle = 'rgba(0,0,0,0.28)';
  ctx.beginPath();
  ctx.ellipse(cx, p.y + p.h + 2, 18, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#1f3550';
  ctx.fillRect(p.x + 4, p.y + p.h - 18, 10, 18);
  ctx.fillRect(p.x + p.w - 14, p.y + p.h - 18, 10, 18);
  ctx.fillStyle = '#2b6fb3';
  ctx.fillRect(p.x + 3, p.y + 12, p.w - 6, p.h - 26);
  ctx.fillStyle = '#84c8ff';
  ctx.fillRect(p.x + 6, p.y + 16, p.w - 12, 6);
  ctx.fillStyle = '#ffd8b0';
  ctx.fillRect(p.x + 6, p.y + 2, p.w - 12, 12);
  ctx.fillStyle = '#e23b2a';
  ctx.fillRect(p.x + 3, p.y + 1, p.w - 6, 5);

  const gx = p.aimX || p.facing;
  const gy = p.aimY || 0;
  const shoulderY = p.y + (p.crouching ? 14 : 24);
  ctx.strokeStyle = '#d8d8d8';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(cx, shoulderY);
  ctx.lineTo(cx + gx * 22, shoulderY + gy * 20);
  ctx.stroke();
  ctx.fillStyle = '#e9b98c';
  ctx.beginPath();
  ctx.arc(cx + gx * 14, shoulderY + gy * 12, 4, 0, Math.PI * 2);
  ctx.fill();

  if (p.muzzle > 0) {
    ctx.fillStyle = '#fff4a0';
    ctx.beginPath();
    ctx.arc(cx + gx * 26, shoulderY + gy * 24, 6, 0, Math.PI * 2);
    ctx.fill();
  }

  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(p.x + p.w / 2 + (p.facing > 0 ? 2 : -6), p.y + 7, 3, 3);
}

function drawAimIndicator(ctx: CanvasRenderingContext2D, p: Player) {
  if (!p.aimX && !p.aimY) return;
  if (Math.abs(p.aimX) < 0.2 && Math.abs(p.aimY) < 0.2) return;
  const cx = p.x + p.w / 2 + p.aimX * 90;
  const cy = p.y + (p.crouching ? 14 : 24) + p.aimY * 80;
  ctx.strokeStyle = 'rgba(255,240,140,0.55)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, 7, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(cx - 10, cy);
  ctx.lineTo(cx - 4, cy);
  ctx.moveTo(cx + 4, cy);
  ctx.lineTo(cx + 10, cy);
  ctx.moveTo(cx, cy - 10);
  ctx.lineTo(cx, cy - 4);
  ctx.moveTo(cx, cy + 4);
  ctx.lineTo(cx, cy + 10);
  ctx.stroke();
}

function drawBullets(ctx: CanvasRenderingContext2D, bullets: Bullet[]) {
  for (const b of bullets) {
    const d = Math.hypot(b.vx, b.vy) || 1;
    const nx = b.vx / d;
    const ny = b.vy / d;
    if (b.friendly) {
      ctx.strokeStyle = '#fff2a0';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(b.x, b.y);
      ctx.lineTo(b.x - nx * 14, b.y - ny * 14);
      ctx.stroke();
      ctx.fillStyle = '#ffd24a';
      ctx.beginPath();
      ctx.arc(b.x, b.y, 2.5, 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.fillStyle = '#ff8a4a';
      ctx.beginPath();
      ctx.arc(b.x, b.y, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,80,40,0.5)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(b.x, b.y);
      ctx.lineTo(b.x - nx * 10, b.y - ny * 10);
      ctx.stroke();
    }
  }
}

function drawParticles(ctx: CanvasRenderingContext2D, particles: Particle[]) {
  for (const pt of particles) {
    const a = Math.max(0, pt.life / pt.max);
    ctx.globalAlpha = a;
    ctx.fillStyle = pt.color;
    ctx.fillRect(pt.x, pt.y, pt.size, pt.size);
  }
  ctx.globalAlpha = 1;
}

function drawArena(ctx: CanvasRenderingContext2D, s: GameState) {
  const gx = s.levelWidth - 320;
  ctx.fillStyle = '#1c2a1f';
  ctx.fillRect(gx, s.groundY - 180, 30, 180);
  ctx.fillRect(gx + 260, s.groundY - 180, 30, 180);
  ctx.fillStyle = '#2a3d2c';
  ctx.fillRect(gx, s.groundY - 190, 290, 20);
  ctx.fillStyle = '#8a2f20';
  ctx.fillRect(gx + 30, s.groundY - 160, 230, 22);
  ctx.fillStyle = '#ffd24a';
  ctx.font = 'bold 16px monospace';
  ctx.fillText('BASE', gx + 110, s.groundY - 144);

  if (s.player.x < 1400) {
    ctx.fillStyle = '#2a3f2f';
    ctx.fillRect(24, s.groundY - 120, 8, 120);
    ctx.fillStyle = '#5ce0a8';
    ctx.font = 'bold 14px monospace';
    ctx.fillText('START', 40, s.groundY - 100);
  }
}

function drawVignette(ctx: CanvasRenderingContext2D) {
  const g = ctx.createRadialGradient(VIEW_W / 2, VIEW_H / 2, VIEW_H * 0.35, VIEW_W / 2, VIEW_H / 2, VIEW_H * 0.85);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);
}

function drawMiniHighScore(ctx: CanvasRenderingContext2D, high: number) {
  if (high <= 0) return;
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.fillRect(VIEW_W - 158, VIEW_H - 26, 146, 18);
  ctx.fillStyle = '#9fc08a';
  ctx.font = '11px monospace';
  ctx.fillText('BEST ' + String(high).padStart(6, '0'), VIEW_W - 150, VIEW_H - 13);
}

