  pointer-events: auto;
}
.tc-btn.small { width: 46px; height: 46px; font-size: 15px; }
.tc-btn.jump { background: rgba(60,100,180,0.88); border-color: #7ba8e8; }
.tc-btn.shoot { background: rgba(200,120,40,0.9); border-color: #ffc06a; }
.tc-btn:active, .tc-btn.pressed { filter: brightness(1.4); transform: scale(0.95); }

.quick-keys {
  position: absolute;
  top: 8px;
  right: 8px;
  display: flex;
  gap: 4px;
  align-items: center;
  z-index: 14;
  pointer-events: auto;
  background: rgba(6,14,9,0.8);
  border: 1px solid #31563f;
  border-radius: 8px;
  padding: 4px 6px;
}
.qk-label { font-size: 10px; color: #8fb878; letter-spacing: 1px; }
.qk-btn {
  pointer-events: auto;
  border: 1px solid #4e7c5a;
  background: #182e1f;
  color: #eaf4dd;
  border-radius: 5px;
  font-size: 11px;
  padding: 4px 8px;
  cursor: pointer;
  letter-spacing: 1px;
}
.qk-btn:hover { background: #284736; }
.qk-btn:active { transform: scale(0.94); background: #3f6b4f; }

.tips { text-align: center; font-size: 12px; color: #8fae80; letter-spacing: 1px; padding: 0 4px; }

@media (max-width: 720px) {
  .game-root { padding: 4px; gap: 2px; }
  .game-title { font-size: 13px; }
  .title-sub { display: none; }
  .live-status { font-size: 10px; }
  .hud-top { grid-template-columns: auto 1fr; padding: 6px 8px; gap: 6px; }
  .hud-block { min-width: 0; padding: 4px 8px; }
  .hud-block.center { display: none; }
  .hud-score { font-size: 15px; }
  .hud-btn { width: 28px; height: 28px; font-size: 12px; }
  .hint-bar { top: 62px; font-size: 10px; padding: 3px 8px; }
  .boss-bar-wrap { top: 88px; }
  .panel { padding: 16px 18px; }
  .tips { font-size: 10px; }
  .tc-btn { width: 50px; height: 50px; font-size: 17px; }
  .tc-btn.small { width: 40px; height: 40px; font-size: 13px; }
  .quick-keys { transform: scale(0.85); transform-origin: top right; }
}
@media (max-width: 420px) {
  .game-root { padding: 3px; }
  .tc-btn { width: 46px; height: 46px; font-size: 16px; }
  .tc-btn.small { width: 36px; height: 36px; font-size: 12px; }
  .tc-pad { gap: 4px; }
  .tc-actions { gap: 8px; }
  .touch-controls { padding: 6px 8px; }
  .quick-keys { display: none; }
}
